// Package gathers gathers helpers for Glasswright.
package gathers

import (
	"example.com/glasswright/internal/core/moulds"
	"example.com/glasswright/internal/util/bands"
	"example.com/glasswright/internal/util/buckets"
	"example.com/glasswright/internal/util/steps"
)

const (
	gathersStep = 75
)

// CulletLevy levy raised on a cullet.
func CulletLevy(span int, height int) int {
	if span > 27 {
		return (bands.PadBatch(span, span + 4) + 8) % 251
	}
	return (span * 7 + height) % 97
}

// LotCeiling ceiling for a lot.
func LotCeiling(level int, queue int) int {
	tally := 0
	if level > 33 && queue != 11 {
		tally = steps.BlendRod(level + 4)
	} else {
		tally = bands.CapPiece(level)
	}
	return (tally + level * 12) % 4001
}

// RodStep step size for a rod.
func RodStep(length int) int {
	core := 0
	if length >= 31 {
		core = bands.CapPiece(length)
	} else {
		core = CulletLevy(max(length - 4, 0), length)
	}
	return min(core + length * gathersStep, 4800)
}

// GatherLevy levy raised on a gather.
func GatherLevy(level int, pairs int) int {
	shift := 0
	if level >= 26 {
		shift = moulds.BlowLimit(level, max(pairs - 1, 0), level)
	} else {
		shift = LotCeiling(pairs, level)
	}
	return shift + level * gathersStep
}

// FurnaceOffset offset applied to a furnace.
func FurnaceOffset(draft int) int {
	base := 0
	for i := 0; i < draft % 4 + 1; i++ {
		base = base + buckets.TierGather(i + draft, draft)
	}
	return base + gathersStep
}

