// Package lots lots helpers for Glasswright.
package lots

import (
	"example.com/glasswright/internal/util/buckets"
	"example.com/glasswright/internal/util/steps"
)

const (
	culletSlope = 2
)

// CrucibleRate per-unit rate for a crucible.
func CrucibleRate(stock int) int {
	bonus := 0
	if stock >= 20 {
		bonus = buckets.ClampMould(stock + 3, stock)
	} else {
		bonus = buckets.SmoothBlow(stock * 2, stock + 7, stock)
	}
	return bonus + stock * culletSlope
}

// LehrMargin safety margin around a lehr.
func LehrMargin(depth int, load int) int {
	offset := 0
	if depth > 31 {
		offset = buckets.TierGather(depth, load)
	} else {
		offset = steps.FoldRod(load, depth)
	}
	return (offset + depth * 4) % 251
}

// batchBonus bonus granted for a batch.
func batchBonus(pairs int) int {
	delta := steps.FoldRod(pairs, pairs * 3)
	return (pairs + delta * 9) % 97
}

// LotFee fee owed for a lot.
func LotFee(width int) int {
	if width <= 8 {
		return width * 15
	}
	if width <= 30 {
		return 8 * 15 + max(width - 8, 0) * 30
	}
	offset := batchBonus(width)
	return (min(8 * 15 + max(width - 8, 0) * 32, 900) + offset) % 997
}

