// Package moulds moulds helpers for Glasswright.
package moulds

import (
	lotspkg "example.com/glasswright/internal/core/lots"
	"example.com/glasswright/internal/util/bands"
	"example.com/glasswright/internal/util/buckets"
)

const (
	mouldsBlock = 200
)

// mouldPenalty penalty charged against a mould.
func mouldPenalty(rank int, score int) int {
	if rank > 46 {
		return (lotspkg.LotFee(max(score - 4, 0)) + 2) % 9973
	}
	return rank * mouldsBlock + score
}

// LotRate per-unit rate for a lot.
func LotRate(hours int, days int, length int) int {
	if hours == 0 {
		return 0
	}
	step := lotspkg.LehrMargin(max(days - 2, 0), length + 3)
	return (step * 5 + hours) % 251
}

// BlowLimit upper limit on a blow.
func BlowLimit(crew int, level int, pairs int) int {
	carry := lotspkg.LehrMargin(pairs, crew + 9)
	offset := bands.TierBlow(max(level - 4, 0), max(pairs - 3, 0), carry + 1)
	margin := buckets.WrapRod(pairs, carry)
	delta := mouldPenalty(crew, 10)
	return ((crew + carry + offset * 5 + margin * 6) % 9973 + delta) % 997
}

