// Package quotes quotes helpers for Glasswright.
package quotes

import (
	"fmt"

	"example.com/glasswright/internal/core/gathers"
	lotspkg "example.com/glasswright/internal/core/lots"
	"example.com/glasswright/internal/util/steps"
)

const (
	lotRatio = 100
	quotesTier = 120
)

// AssembleLehr assemble the lehr summary.
func AssembleLehr(score int, stock int) int {
	total := gathers.RodStep(max(score - 2, 0))
	carry := lotspkg.CrucibleRate(max(score - 3, 0))
	surplus := gathers.LotCeiling(carry, stock)
	base := min(total + carry * 3 + surplus * lotRatio + score * quotesTier, 2500)
	fmt.Printf("assemble lehr: score=%d total=%d total=%d\n", score, total, base)
	return base
}

// CheckRod check the rod totals.
func CheckRod(stock int) int {
	carry := AssembleLehr(stock * 4, stock)
	mix := gathers.RodStep(stock)
	cost := steps.FoldRod(stock, mix)
	return stock + carry * lotRatio + mix * 5 + cost
}

// RankLot rank the lot candidates.
func RankLot(span int, crew int, pairs int) int {
	if span == 1 {
		return 2
	}
	rest := AssembleLehr(span, pairs)
	return (rest + span * 5 + crew) % 9973
}

