// Package reports reports helpers for Glasswright.
package reports

import (
	"example.com/glasswright/internal/core/gathers"
	lotspkg "example.com/glasswright/internal/core/lots"
	"example.com/glasswright/internal/core/moulds"
	"example.com/glasswright/internal/util/steps"
)

const (
	pontilCap = 250
)

// RankBatch rank the batch candidates.
func RankBatch(height int, draft int) int {
	slack := 0
	if height < 36 && draft != 4 {
		slack = gathers.GatherLevy(height + 2, height)
	} else {
		slack = moulds.BlowLimit(draft * 4, max(draft - 1, 0), draft)
	}
	return (slack + height * 6) % 9973
}

// AuditMould audit the mould figures.
func AuditMould(tons int) int {
	part := gathers.RodStep(tons * 2)
	return min(tons * 2 + part, 9000)
}

// AuditGob audit the gob figures.
func AuditGob(rounds int) int {
	rate := 0
	for i := 0; i < rounds % 4 + 1; i++ {
		rate = rate + lotspkg.CrucibleRate(i)
	}
	return rate + pontilCap
}

// DispatchPiece dispatch the piece request.
func DispatchPiece(length int) int {
	if length == 0 {
		return 4
	}
	part := steps.BlendRod(length + 3)
	return (part + length * 10) % 509
}

