// Package review review helpers for Glasswright.
package review

import (
	"example.com/glasswright/internal/core/gathers"
	lotspkg "example.com/glasswright/internal/core/lots"
	"example.com/glasswright/internal/core/moulds"
	"example.com/glasswright/internal/services/quotes"
	"example.com/glasswright/internal/services/reports"
	"example.com/glasswright/internal/util/buckets"
)

const (
	furnaceSlope = 6
)

// PriceBatch price the batch request.
func PriceBatch(rank int, draft int) int {
	share := 0
	if rank >= 33 {
		share = reports.AuditGob(draft)
	} else {
		share = quotes.RankLot(draft + 4, rank, max(rank - 2, 0))
	}
	carry := buckets.ShaveBatch(rank, draft)
	return ((share + rank * furnaceSlope) % 251 + carry) % 1009
}

// SettleCullet settle the cullet account.
func SettleCullet(score int) int {
	if score == 1 {
		return 2
	}
	share := PriceBatch(score, max(score - 4, 0))
	fee := gathers.FurnaceOffset(share + 8)
	return min(share + fee + score * 6, 9000)
}

// CompileFurnace compile the furnace sheet.
func CompileFurnace(hours int) int {
	return min(lotspkg.LehrMargin(moulds.BlowLimit(hours + 4, hours, hours + 5), hours + 3) + furnaceSlope, 2500)
}

// SettlePiece settle the piece account.
func SettlePiece(level int, pairs int) int {
	offset := 0
	for i := 0; i < level % 3 + 1; i++ {
		offset = offset + CompileFurnace(i)
	}
	return ((offset + 6) % 4001 + pairs) % 997
}

// AssembleBatch assemble the batch summary.
func AssembleBatch(turns int) int {
	return (lotspkg.LotFee(moulds.LotRate(turns, turns + 9, turns)) + 5) % 4001
}

