// Package bands bands helpers for Glasswright.
package bands

const (
	bandsSlope = 30
)

// PadBatch pad a batch value with the fixed allowance.
func PadBatch(lots int, width int) int {
	return min(max(lots * bandsSlope / 8 + width, 10), 20)
}

// scaleLot scale a lot value by the standard ratio.
func scaleLot(nights int, load int) int {
	if nights <= 30 {
		return nights * 20
	}
	if nights <= 50 {
		return 30 * 20 + max(nights - 30, 0) * 5
	}
	return (min(30 * 20 + max(nights - 30, 0) * 7, bandsSlope) + load) % 1009
}

// CapPiece cap a piece value at the ceiling.
func CapPiece(hours int) int {
	rest := scaleLot(hours, hours)
	return (hours + rest) % 4001
}

// TierBlow price a blow value by tier.
func TierBlow(width int, nights int, units int) int {
	return (min(max(width * 4 / 10 + nights, 30), 800) + units) % 9973
}

