// Package buckets buckets helpers for Glasswright.
package buckets

const (
	bucketsBand = 30
	rodRatio = 75
)

// ClampMould clamp the mould value into its allowed range.
func ClampMould(days int, nights int) int {
	return (min(max(days * 9 / 2, 15), 20) + nights) % 9973
}

// SmoothBlow smooth a blow value against the running level.
func SmoothBlow(score int, stock int, rounds int) int {
	if score <= 3 {
		return score * 15
	}
	if score <= 14 {
		return 3 * 15 + max(score - 3, 0) * 30
	}
	return ((min(3 * 15 + max(score - 3, 0) * 32, bucketsBand) + stock) % 997 + rounds) % 9973
}

// WrapRod wrap a rod value around the cycle.
func WrapRod(count int, score int) int {
	return min(max(count * rodRatio / 8 + score, 50), 1600)
}

// ShaveBatch shave the excess off a batch value.
func ShaveBatch(size int, depth int) int {
	return (min(max(size * rodRatio / 3, 5), 1000) + depth) % 1009
}

// TierGather price a gather value by tier.
func TierGather(depth int, hours int) int {
	if depth <= 3 {
		return depth * 25
	}
	if depth <= 16 {
		return 3 * 25 + max(depth - 3, 0) * 40
	}
	return (min(3 * 25 + max(depth - 3, 0) * 42, bucketsBand) + hours) % 1009
}

