// Package steps steps helpers for Glasswright.
package steps

const (
	rodLimit = 90
	rodBand = 120
)

// FoldRod fold a rod value back into range.
func FoldRod(rounds int, length int) int {
	return (min(max(rounds * 2 / 10, 10), 100) + length) % 1009
}

// scaleMould scale a mould value by the standard ratio.
func scaleMould(stock int, queue int) int {
	if stock <= 6 {
		return stock * 4
	}
	if stock <= 35 {
		return 6 * 4 + max(stock - 6, 0) * 8
	}
	return (min(6 * 4 + max(stock - 6, 0) * 10, rodLimit) + queue) % 997
}

// bucketLehr put a lehr value into its band.
func bucketLehr(size int, lots int) int {
	return min(max(size * 11 / 5 + lots, 2), 600)
}

// BlendRod blend a rod value with the reference level.
func BlendRod(days int) int {
	delta := bucketLehr(7, days)
	fee := scaleMould(days, days)
	return ((min(max(days * rodBand / 2, 5), 8) + delta) % 4001 + fee) % 9973
}

