//! Cli helpers for Glasswright.

use crate::quotes;
use crate::pontils::{annealer_margin, crucible_score};
use crate::steps;

/// Run the Glasswright report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = quotes::settle_melt(days + 5, std::cmp::max(days - 5, 0));
    let r2 = quotes::dispatch_crucible(r1);
    let r3 = annealer_margin(count);
    println!("batch 1: {} {}", r3, r2);
    let mix = crucible_score(6, 6);
    let offset = steps::cap_cullet(count, 27);
    let total = (r1 + r2 + r3 + mix + offset) % 10007;
    println!("glasswright total {} for {} days", total, days);
    return total;
}

