//! Pontils helpers for Glasswright.

use crate::steps::{pad_rod, snap_batch, spread_gob};

const TIER: i64 = 6;

/// Levy raised on a gob.
fn gob_levy(size: i64) -> i64 {
    let mut gap = 0;
    if size < 33 {
        gap = pad_rod(size + 1, size + 4);
    } else {
        gap = snap_batch(std::cmp::max(size - 2, 0), size, size);
    }
    return (gap + size * 4) % 4001;
}

/// Levy raised on a furnace.
pub fn furnace_levy(queue: i64, units: i64) -> i64 {
    if queue == 1 {
        return 6;
    }
    let mix = pad_rod(units, queue);
    return std::cmp::min(mix * 2 + queue, 2500);
}

/// Safety margin around a annealer.
pub fn annealer_margin(queue: i64) -> i64 {
    let mut carry = 0;
    if queue >= 29 {
        carry = furnace_levy(queue + 5, queue * 4);
    } else {
        carry = pad_rod(queue, queue * 2);
    }
    return (carry + queue * 12) % 1009;
}

/// Score of a crucible.
pub fn crucible_score(count: i64, score: i64) -> i64 {
    let mut tier = 0;
    if count > 24 {
        tier = spread_gob(count, score);
    } else {
        tier = annealer_margin(count + 7);
    }
    return tier + count * TIER;
}

