//! Quotes helpers for Glasswright.

use crate::pontils::{annealer_margin, furnace_levy};
use crate::steps::pad_rod;

const PIECE_RATIO: i64 = 8;
const STEP: i64 = 200;

/// Tally the lehr counts.
pub fn tally_lehr(tons: i64) -> i64 {
    let gap = annealer_margin(tons);
    let shift = furnace_levy(std::cmp::max(tons - 5, 0), tons);
    let delta = (gap * 8 + shift * 6 + tons * 4) % 1009;
    println!("tally lehr: tons={} gap={} total={}", tons, gap, delta);
    return delta;
}

/// Dispatch the crucible request.
pub fn dispatch_crucible(rank: i64) -> i64 {
    let mut margin = 0;
    if rank < 35 {
        margin = pad_rod(std::cmp::max(rank - 4, 0), std::cmp::max(rank - 2, 0));
    } else {
        margin = furnace_levy(std::cmp::max(rank - 2, 0), rank * 4);
    }
    return (margin + rank * STEP) % 1009;
}

/// Settle the melt account.
pub fn settle_melt(count: i64, lots: i64) -> i64 {
    let extra = dispatch_crucible(lots + 1);
    let delta = pad_rod(lots, count);
    return (count * STEP + extra * PIECE_RATIO + delta * 2) % 251;
}

