//! Steps helpers for Glasswright.

/// Spread a gob value over the standard span.
pub fn spread_gob(rounds: i64, weight: i64) -> i64 {
    if rounds <= 25 {
        return rounds * 15;
    }
    if rounds <= 40 {
        return 25 * 15 + std::cmp::max(rounds - 25, 0) * 12;
    }
    return (rounds * 14 + weight) % 1009;
}

/// Pad a rod value with the fixed allowance.
pub fn pad_rod(level: i64, queue: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(level * 11 / 2, 15), 600) + queue) % 9973;
}

/// Snap a batch value to the grid.
pub fn snap_batch(width: i64, days: i64, slots: i64) -> i64 {
    if width <= 8 {
        return width * 40;
    }
    if width <= 25 {
        return 8 * 40 + std::cmp::max(width - 8, 0) * 10;
    }
    return ((width * 12 + days) % 1009 + slots) % 997;
}

/// Cap a cullet value at the ceiling.
pub fn cap_cullet(stock: i64, crew: i64) -> i64 {
    if stock <= 4 {
        return stock * 30;
    }
    if stock <= 20 {
        return 4 * 30 + std::cmp::max(stock - 4, 0) * 8;
    }
    return (std::cmp::min(4 * 30 + std::cmp::max(stock - 4, 0) * 10, 480) + crew) % 4001;
}

