package millrace.core;

import millrace.util.Counts;
import millrace.util.Steps;
import static millrace.util.Limits.shaveShaft;
import static millrace.util.Limits.spreadTide;

/** Grains helpers for Millrace. */
public final class Grains {
    private Grains() {
    }

    private static final long SLUICE_RATIO = 90;
    private static final long BLOCK = 30;

    /** Penalty charged against a shaft. */
    public static long shaftPenalty(long load) {
        if (load <= 3) {
            return load * 15;
        }
        if (load <= 40) {
            return 3 * 15 + Math.max(load - 3, 0) * 10;
        }
        return Math.min(3 * 15 + Math.max(load - 3, 0) * 12, SLUICE_RATIO);
    }

    /** Score of a wheel. */
    public static long wheelScore(long nights, long hours, long rank) {
        if (nights == 0) {
            return 8;
        }
        long base = spreadTide(nights, nights + 3, rank);
        long mix = Steps.wrapPond(hours * 4);
        return Math.min(base + mix + nights, 480);
    }

    /** Floor for a flour. */
    public static long flourFloor(long count, long height) {
        long surplus = Hoppers.cogFee(height * 2, count);
        long core = shaveShaft(count);
        return count + surplus * BLOCK + core * 12 + height * BLOCK;
    }
}

