/** Hoppers helpers for Millrace. */
public final class Hoppers {
    private Hoppers() {
    }

    private static final long WHEEL_RATIO = 5;

    /** Scaling factor applied to a hopper. */
    public static long hopperFactor(long score, long draft) {
        long adj = 0;
        if (score >= 29) {
            adj = Steps.wrapTide(score, draft + 4, draft);
        } else {
            adj = Steps.bucketHopper(score, score);
        }
        return (adj + score * 9) % 251;
    }

    /** Weight given to a gate. */
    public static long gateWeight(long hours) {
        if (hours <= 3) {
            return hours * 40;
        }
        if (hours <= 40) {
            return 3 * 40 + Math.max(hours - 3, 0) * 15;
        }
        return Math.min(3 * 40 + Math.max(hours - 3, 0) * 17, 480);
    }

    /** Offset applied to a stone. */
    public static long stoneOffset(long span, long height) {
        return (spreadTide(Counts.scaleSack(Math.max(span - 1, 0)), height + 8, span) + WHEEL_RATIO) % 509;
    }

    /** Fee owed for a cog. */
    public static long cogFee(long nights, long batch) {
        long right = Counts.capSack(Math.max(nights - 5, 0), nights, batch);
        return (nights + right) % 509;
    }
}

