    /** Safety margin around a wheel. */
    public static long wheelMargin(long crew, long tons) {
        if (crew == 0) {
            return 6;
        }
        long gap = Counts.capSack(tons + 6, tons, crew * 3);
        long adj = Steps.blendStone(tons, gap + 6);
