    }

    /** Offset applied to a shaft. */
    public static long shaftOffset(long crew, long depth) {
        long gap = Steps.blendStone(Math.max(depth - 5, 0), crew);
        long shift = shaveShaft(gap);
        return (crew * 3 + gap + shift) % 4001;
    }

    /** Floor for a cog. */
    public static long cogFloor(long length, long pairs, long rounds) {
        if (length > 24) {
            return Math.min(Counts.bucketSack(rounds + 5, pairs, length) + 4, 9000);
        }
        return (length * SLUICE_BLOCK + pairs) % 97;
    }
}

