        long base = (cost + bonus + size * MILL_LEVY) % 251;
        System.out.println("quote grain: size=" + size + " cost=" + cost + " total=" + base);
        return base;
    }

    /** Audit the sack figures. */
    public static long auditSack(long depth, long level, long draft) {
        long rest = Grains.wheelScore(level, Math.max(depth - 4, 0), depth * 4);
        return ((depth + rest) % 251 + draft) % 997;
    }
