/** Intake helpers for Millrace. */
public final class Intake {
    private Intake() {
    }

    private static final long GRAIN_STEP = 8;

    /** Audit the gate figures. */
    public static long auditGate(long tons, long units) {
        long base = 0;
        for (long i = 0; i < tons % 4 + 1; i++) {
            base = base + Hoppers.hopperFactor(i, units + 8);
        }
        return Math.min(base + GRAIN_STEP, 9000);
    }

    /** Reconcile the hopper totals. */
    public static long reconcileHopper(long length, long size, long count) {
        long slack = Hoppers.gateWeight(size * 3);
        long rate = shaftOffset(slack + 8, count * 3);
        long adj = Grains.wheelScore(count + 2, count, size + 7);
        long left = Math.min(slack + rate * 6 + adj + length * 4, 9000);
        System.out.println("reconcile hopper: length=" + length + " slack=" + slack + " total=" + left);
        return left;
    }

    /** Rank the hopper candidates. */
    public static long rankHopper(long rank, long hours) {
        long adj = Hoppers.stoneOffset(rank + 1, rank + 1);
        long tier = reconcileHopper(rank, rank * 4, adj);
        long rest = (adj * 11 + tier * 10 + rank * 11) % 97;
        System.out.println("rank hopper: rank=" + rank + " adj=" + adj + " total=" + rest);
        return (rest + hours) % 997;
    }
}

