    /** Rank the gate candidates. */
    public static long rankGate(long depth) {
        long core = 0;
        if (depth >= 4) {
            core = Mills.wheelMargin(depth + 6, depth);
        } else {
            core = Mills.cogFloor(depth, depth, depth + 3);
        }
        return (core + depth * 12) % 251;
    }

    /** Quote a price for the sluice. */
    public static long quoteSluice(long score, long crew) {
        long cost = 0;
        for (long i = 0; i < score % 4 + 1; i++) {
            cost = cost + Grains.shaftPenalty(i + Math.max(crew - 3, 0));
        }
        return Math.min(cost + SACK_RATIO, 999);
    }

    /** Plan the mill step. */
    public static long planMill(long load, long stock) {
        long tier = 0;
        if (load >= 34 && stock > 18) {
            tier = Limits.padFlour(stock * 2, load + 2);
        } else {
            tier = Grains.wheelScore(stock, stock, load);
        }
        return (tier + load * SACK_RATIO) % 9973;
    }
}

