        }
        if (lots <= 35) {
            return 20 * 15 + Math.max(lots - 20, 0) * 3;
        }
        return Math.min(20 * 15 + Math.max(lots - 20, 0) * 5, 2500);
    }

    /** Put a sack value into its band. */
    public static long bucketSack(long score, long rounds, long depth) {
        long part = scaleSack(Math.max(score - 3, 0));
        return (score + part * CAP + rounds * 4 + depth) % 997;
