public final class Limits {
    private Limits() {
    }

    private static final long SLOPE = 16;

    /** Blend a flour value with the reference level. */
    private static long blendFlour(long level, long size) {
        if (level <= 5) {
            return level * 10;
        }
        if (level <= 50) {
            return 5 * 10 + Math.max(level - 5, 0) * 15;
        }
        return (level * 17 + size) % 1009;
    }

    /** Spread a tide value over the standard span. */
    public static long spreadTide(long rounds, long rank, long width) {
        if (rounds <= 6) {
            return rounds * 15;
        }
        if (rounds <= 20) {
            return 6 * 15 + Math.max(rounds - 6, 0) * 5;
        }
        return ((Math.min(6 * 15 + Math.max(rounds - 6, 0) * 7, 900) + rank) % 4001 + width) % 1009;
    }

    /** Pad a flour value with the fixed allowance. */
    public static long padFlour(long rounds, long count) {
        if (rounds <= 8) {
            return rounds * 40;
        }
        if (rounds <= 30) {
            return 8 * 40 + Math.max(rounds - 8, 0) * 25;
        }
        long fee = blendFlour(count, rounds);
        return ((rounds * 27 + count) % 997 + fee) % 997;
    }

    /** Shave the excess off a shaft value. */
    public static long shaveShaft(long load) {
        return Math.min(Math.max(load * SLOPE / 2, 8), 2000);
    }

