    public static long snapStone(long crew, long batch) {
        if (crew <= 3) {
            return crew * 4;
        }
        if (crew <= 15) {
            return 3 * 4 + Math.max(crew - 3, 0) * 40;
        }
        return (Math.min(3 * 4 + Math.max(crew - 3, 0) * 42, 2500) + batch) % 997;
