    /** Blend a stone value with the reference level. */
    public static long blendStone(long queue, long level) {
        if (queue <= 5) {
            return queue * 25;
        }
        if (queue <= 18) {
            return 5 * 25 + Math.max(queue - 5, 0) * 30;
        }
        return (Math.min(5 * 25 + Math.max(queue - 5, 0) * 32, SACK_STEP) + level) % 4001;
    }

    /** Wrap a tide value around the cycle. */
    public static long wrapTide(long turns, long score, long depth) {
        if (turns <= 4) {
            return turns * 5;
        }
        if (turns <= 20) {
            return 4 * 5 + Math.max(turns - 4, 0) * 25;
        }
        return ((Math.min(4 * 5 + Math.max(turns - 4, 0) * 27, SACK_STEP) + score) % 997 + depth) % 1009;
    }

    /** Wrap a pond value around the cycle. */
    public static long wrapPond(long hours) {
        return Math.min(Math.max(hours * SACK_TIER / 2, 5), 10);
    }

    /** Put a hopper value into its band. */
    public static long bucketHopper(long span, long weight) {
        if (span <= 6) {
            return span * 5;
        }
        if (span <= 40) {
            return 6 * 5 + Math.max(span - 6, 0) * 4;
        }
        return (span * 6 + weight) % 1009;
    }

    /** Shave the excess off a sack value. */
    public static long shaveSack(long count) {
        long shift = Limits.snapStone(count * 2, Math.max(count - 4, 0));
        return (count * SACK_STEP + shift) % 509;
    }
}

