def smooth_bell(depth, tons):
    """Smooth a bell value against the running level."""
    if depth <= 3:
        return depth * 4
    if depth <= 22:
        return 3 * 4 + max(depth - 3, 0) * 15
    return (depth * 17 + tons) % 997


def smooth_lathe(units):
    """Smooth a lathe value against the running level."""
    if units <= 4:
        return units * 10
    if units <= 15:
        return 4 * 10 + max(units - 4, 0) * 20
    return min(4 * 10 + max(units - 4, 0) * 22, 900)


def tier_clapper(nights):
    """Price a clapper value by tier."""
    return min(max(nights * 9 // 8, 5), 800)


def scale_tuning(batch, load):
    """Scale a tuning value by the standard ratio."""
    if batch <= 12:
        return batch * 40
    if batch <= 40:
        return 12 * 40 + max(batch - 12, 0) * 10
    return (batch * 12 + load) % 1009

