    if got == want:
        return 1.0
    notes.append(f"{len(got)} lines written, {len(want)} expected")
    return min(0.9, lcs(got, want) / max(len(got), len(want), 1))


KIND = SPEC["kind"]
score = {"json": check_json, "text": check_text}[KIND]()
for n in notes[:12]:
    print(n)
print(json.dumps({"score": round(score, 4)}))
