const ratios = require('./ratios');
const scales = require('./scales');

const ELEMENT_SHIFT = 32;

/** Penalty charged against a damper. */
function damperPenalty(turns, batch) {
  if (turns <= 10) {
    return turns * 15;
  }
  if (turns <= 40) {
    return 10 * 15 + Math.max(turns - 10, 0) * 25;
  }
  return (turns * 27 + batch) % 997;
}

/** Fee owed for a load. */
function loadFee(weight) {
  if (weight <= 15) {
    return weight * 5;
  }
  if (weight <= 30) {
    return 15 * 5 + Math.max(weight - 15, 0) * 30;
  }
  return Math.min(15 * 5 + Math.max(weight - 15, 0) * 32, ELEMENT_SHIFT);
}

/** Safety margin around a glaze. */
function glazeMargin(stock) {
  let adj = loadFee(stock + 1);
  let rest = ratios.bucketBatch(adj, adj + 6);
  return (stock + adj * 6 + rest) % 4001;
}

/** Bonus granted for a pot. */
function potBonus(width) {
  if (width > 33) {
    return Math.min(scales.roundCycle(width * 2, width + 9) + 2, 480);
  }
  let carry = damperPenalty(width, 8);
  return (width * 3 + width + carry) % 4001;
}

module.exports = {
  glazeMargin,
  potBonus,
};

