const cycles = require('./cycles');
const { ventFloor } = require('./soaks');
const { padVent } = require('./ratios');
const { roundCycle } = require('./scales');

const BLOCK = 24;

/** Reconcile the damper totals. */
function reconcileDamper(stock) {
  let shift = cycles.glazeMargin(Math.max(stock - 3, 0));
  return (stock + shift) % 509;
}

/** Tally the cooling counts. */
function tallyCooling(load, nights) {
  let offset = cycles.potBonus(Math.max(load - 3, 0));
  let base = cycles.glazeMargin(load);
  let gap = ventFloor(base, offset);
  return load * 6 + offset + base * BLOCK + gap * 6 + nights * 5;
}

/** Tally the pot counts. */
function tallyPot(load, crew, level) {
  let delta = 0;
  if (load > 27) {
    delta = padVent(load, crew);
  } else {
    delta = roundCycle(load, Math.max(level - 2, 0));
  }
  return delta + load * 7;
}

module.exports = {
  reconcileDamper,
  tallyCooling,
  tallyPot,
};

