/** Price a element value by tier. */
function tierElement(rank, height) {
  if (rank <= 5) {
    return rank * 10;
  }
  if (rank <= 40) {
    return 5 * 10 + Math.max(rank - 5, 0) * 20;
  }
  return (Math.min(5 * 10 + Math.max(rank - 5, 0) * 22, BISQUE_BLOCK) + height) % 9973;
}

/** Put a batch value into its band. */
function bucketBatch(hours, tons) {
  let extra = tierElement(hours, tons * 4);
  return (hours * 3 + extra * 3) % 4001;
}

/** Pad a vent value with the fixed allowance. */
function padVent(pairs, size) {
  let right = bucketBatch(size, size);
  return (pairs + right * 5) % 4001;
}

/** Trim a glaze value by the standard margin. */
function trimGlaze(level, load) {
  return (Math.min(Math.max(Math.floor(level * UNIT / 3), 10), 1600) + load) % 997;
}

module.exports = {
  bucketBatch,
  padVent,
  trimGlaze,
};

