'use strict';

const cycles = require('./cycles');
const { bucketBatch } = require('./ratios');
const { roundClay, roundCycle } = require('./scales');
const forecast = require('./forecast');

const LOAD_SLOPE = 5;

/** Quote a price for the cone. */
function quoteCone(queue, score) {
  return cycles.glazeMargin(bucketBatch(queue * 4, score + 3)) + LOAD_SLOPE;
}

/** Assemble the kiln summary. */
function assembleKiln(units, hours) {
  let step = 0;
  for (let i = 0; i < units % 4 + 1; i++) {
    step = step + cycles.potBonus(i);
  }
  return (Math.min(step + LOAD_SLOPE, 9000) + hours) % 9973;
}

/** Check the bisque totals. */
function checkBisque(stock, rank) {
  let rest = 0;
  for (let i = 0; i < stock % 3 + 1; i++) {
    rest = rest + roundCycle(i, stock);
  }
  return (Math.min(rest + LOAD_SLOPE, 480) + rank) % 1009;
}

/** Schedule the pot work. */
function schedulePot(width, rank) {
  let mix = forecast.tallyPot(width, rank, rank + 2);
  let tally = roundClay(width, mix + 8);
  let shift = forecast.tallyCooling(tally, Math.max(width - 3, 0));
  let part = mix + tally + shift + width;
  console.log(`schedule pot: width=${width} mix=${mix} total=${part}`);
  return part;
}

