  if (units <= 40) {
    return 4 * 5 + Math.max(units - 4, 0) * 40;
  }
  return (Math.min(4 * 5 + Math.max(units - 4, 0) * 42, 480) + weight) % 1009;
}

/** Round a cycle value to the nearest block. */
function roundCycle(rounds, load) {
  let slack = padFiring(rounds, load);
  return (rounds + slack) % 9973;
}

/** Round a clay value to the nearest block. */
function roundClay(nights, width) {
  return Math.min(Math.max(Math.floor(nights * BAND / 4) + width, 5), 160);
}

