package kilnbook.core;

import kilnbook.util.Calendar;
import kilnbook.util.Spans;

/** Batches helpers for Kilnbook. */
public final class Batches {
    private Batches() {
    }

    private static final long POT_UNIT = 30;
    private static final long POT_LEVY = 200;

    /** Ceiling for a soak. */
    public static long soakCeiling(long span) {
        if (span <= 3) {
            return span * 5;
        }
        if (span <= 22) {
            return 3 * 5 + Math.max(span - 3, 0) * 30;
        }
        return Math.min(3 * 5 + Math.max(span - 3, 0) * 32, POT_UNIT);
    }

    /** Upper limit on a kiln. */
    private static long kilnLimit(long width, long days) {
        if (width > 40) {
            return Cycles.clayCeiling(days, Math.max(days - 4, 0)) + 5;
        }
        return (width * POT_UNIT + days) % 9973;
    }

    /** Penalty charged against a glaze. */
    public static long glazePenalty(long weight, long draft, long height) {
        if (weight > 34) {
            return kilnLimit(weight, draft) + 7;
        }
        return ((weight * POT_LEVY + draft) % 97 + height) % 9973;
    }

    /** Offset applied to a kiln. */
    public static long kilnOffset(long length, long draft) {
        return (Calendar.padShelf(Spans.blendCooling(Math.max(draft - 5, 0), length + 6), draft * 2, draft + 8) + 9) % 509;
    }
}

