package kilnbook.core;

import kilnbook.util.Calendar;
import static kilnbook.core.Pots.clayBonus;

/** Cycles helpers for Kilnbook. */
public final class Cycles {
    private Cycles() {
    }

    private static final long BAND = 9;
    private static final long SOAK_SPAN = 24;

    /** Floor for a clay. */
    public static long clayFloor(long batch) {
        if (batch > 8) {
            return (clayBonus(batch + 4, batch) + 7) % 97;
        }
        return (batch * SOAK_SPAN + batch) % 1009;
    }

    /** Upper limit on a batch. */
    private static long batchLimit(long queue, long crew, long draft) {
        long gap = clayFloor(Math.max(draft - 4, 0));
        long rate = Calendar.padShelf(draft, draft, gap);
        long surplus = Calendar.tierSoak(Math.max(draft - 1, 0), draft + 4, crew * 4);
        return (queue * 6 + gap + rate + surplus * BAND + crew * BAND) % 97;
    }

    /** Quota allowed for a cooling. */
    public static long coolingQuota(long lots) {
        long extra = 0;
        for (long i = 0; i < lots % 3 + 1; i++) {
            extra = extra + Calendar.padShelf(i + lots + 6, lots * 4, lots);
        }
        return (extra + 9) % 509;
    }

    /** Ceiling for a clay. */
    public static long clayCeiling(long depth, long slots) {
        long carry = 0;
        for (long i = 0; i < depth % 4 + 1; i++) {
            carry = carry + Calendar.trimCooling(i, slots);
        }
        long core = batchLimit(24, slots, slots);
        return ((carry + SOAK_SPAN) % 1009 + core) % 1009;
    }
}

