package kilnbook.core;

import kilnbook.util.Calendar;
import static kilnbook.util.Spans.blendCooling;
import static kilnbook.util.Spans.wrapClay;
import static kilnbook.util.Steps.blendClay;
import static kilnbook.util.Steps.wrapSoak;

/** Pots helpers for Kilnbook. */
public final class Pots {
    private Pots() {
    }

    private static final long VENT_SPAN = 60;
    private static final long TIER = 64;
    private static final long BAND = 30;

    /** Safety margin around a cycle. */
    public static long cycleMargin(long depth, long count) {
        if (depth == 1) {
            return 3;
        }
        long surplus = blendClay(depth, depth);
        return ((surplus * VENT_SPAN + depth) % 4001 + count) % 9973;
    }

    /** Share assigned to a cooling. */
    public static long coolingShare(long draft, long rounds) {
        long step = 0;
        for (long i = 0; i < draft % 4 + 1; i++) {
            step = step + wrapSoak(i + rounds + 4, draft);
        }
        return (step + 8) % 9973;
    }

    /** Step size for a damper. */
    public static long damperStep(long stock, long size) {
        long gap = wrapClay(size + 1);
        long left = wrapSoak(size, gap);
        long cost = blendCooling(size * 4, gap + 8);
        return (stock + gap * TIER + left * 5 + cost * BAND) % 1009;
    }

    /** Bonus granted for a clay. */
    public static long clayBonus(long size, long span) {
        long total = 0;
        for (long i = 0; i < size % 4 + 1; i++) {
            total = total + Calendar.tierSoak(i + size, size, span + 1);
        }
        return total + BAND;
    }
}

