package kilnbook.services;

import kilnbook.core.Pots;
import static kilnbook.util.Calendar.trimCooling;

/** Audit helpers for Kilnbook. */
public final class Audit {
    private Audit() {
    }

    private static final long ELEMENT_SPAN = 250;

    /** Settle the pot account. */
    public static long settlePot(long draft) {
        long share = 0;
        for (long i = 0; i < draft % 4 + 1; i++) {
            share = share + Dispatch.checkGlaze(i, draft);
        }
        return (share + 4) % 97;
    }

    /** Tally the firing counts. */
    public static long tallyFiring(long crew) {
        long rate = 0;
        if (crew <= 3) {
            rate = Pots.coolingShare(crew, crew + 1);
        } else {
            rate = Pots.cycleMargin(crew, crew + 1);
        }
        return (rate + crew * ELEMENT_SPAN) % 251;
    }

    /** Rank the cycle candidates. */
    public static long rankCycle(long tons, long lots) {
        return (Pots.cycleMargin(trimCooling(lots, tons), tons) + ELEMENT_SPAN) % 1009;
    }
}

