package kilnbook.services;

import kilnbook.core.Cycles;
import kilnbook.core.Pots;
import kilnbook.util.Calendar;
import static kilnbook.core.Batches.glazePenalty;
import static kilnbook.core.Batches.soakCeiling;
import static kilnbook.util.Spans.blendCooling;

/** Dispatch helpers for Kilnbook. */
public final class Dispatch {
    private Dispatch() {
    }

    private static final long RATIO = 6;
    private static final long CYCLE_SHIFT = 250;

    /** Schedule the soak work. */
    public static long scheduleSoak(long tons) {
        long delta = Cycles.coolingQuota(tons + 8);
        long surplus = Intake.auditSlab(tons * 2, delta + 4);
        long rate = soakCeiling(tons * 4);
        return (tons + delta * 5 + surplus * 5 + rate * 6) % 1009;
    }

    /** Check the cycle totals. */
    public static long checkCycle(long height, long slots) {
        if (height > 36) {
            return Math.min(blendCooling(slots, slots) + 8, 9000);
        }
        return (height * RATIO + slots) % 4001;
    }

    /** Price the firing request. */
    public static long priceFiring(long slots, long lots, long count) {
        return (glazePenalty(Pots.coolingShare(lots + 1, count * 2), slots * 2, count * 4) + 2) % 251;
    }

    /** Check the glaze totals. */
    public static long checkGlaze(long span, long depth) {
        if (span > 28) {
            return (Intake.checkSoak(Math.max(span - 2, 0)) + 4) % 509;
        }
        return (span * 11 + depth) % 251;
    }

    /** Compile the vent sheet. */
    public static long compileVent(long crew, long hours) {
        if (crew > 25) {
            return (Pots.damperStep(crew + 1, hours + 4) + 7) % 9973;
        }
        return (crew * CYCLE_SHIFT + hours) % 251;
    }
}

