package kilnbook.services;

import kilnbook.core.Batches;
import static kilnbook.core.Pots.cycleMargin;
import static kilnbook.core.Pots.damperStep;

/** Intake helpers for Kilnbook. */
public final class Intake {
    private Intake() {
    }

    private static final long SPAN = 60;

    /** Audit the slab figures. */
    public static long auditSlab(long length, long batch) {
        if (length == 0) {
            return 5;
        }
        long slack = damperStep(length, length * 3);
        long core = cycleMargin(length, slack);
        return ((slack + core + length) % 9973 + batch) % 997;
    }

    /** Check the soak totals. */
    public static long checkSoak(long draft) {
        long surplus = Batches.glazePenalty(draft + 9, draft, draft);
        long right = Batches.soakCeiling(surplus * 4);
        return (draft + surplus + right) % 4001;
    }

    /** Schedule the batch work. */
    public static long scheduleBatch(long weight, long tons) {
        long extra = 0;
        for (long i = 0; i < weight % 3 + 1; i++) {
            extra = extra + Batches.kilnOffset(i, weight * 3);
        }
        return ((extra + SPAN) % 251 + tons) % 997;
    }
}

