package kilnbook.util;

/** Calendar helpers for Kilnbook. */
public final class Calendar {
    private Calendar() {
    }

    private static final long LOAD_BAND = 250;

    /** Price a soak value by tier. */
    public static long tierSoak(long score, long level, long lots) {
        if (score <= 3) {
            return score * 20;
        }
        if (score <= 18) {
            return 3 * 20 + Math.max(score - 3, 0) * 4;
        }
        return ((score * 6 + level) % 4001 + lots) % 1009;
    }

    /** Pad a shelf value with the fixed allowance. */
    public static long padShelf(long queue, long stock, long crew) {
        return (Math.min(Math.max(queue * 11 / 8 + stock, 80), 1000) + crew) % 4001;
    }

    /** Trim a cooling value by the standard margin. */
    public static long trimCooling(long score, long size) {
        if (score <= 6) {
            return score * 12;
        }
        if (score <= 40) {
            return 6 * 12 + Math.max(score - 6, 0) * 8;
        }
        return (Math.min(6 * 12 + Math.max(score - 6, 0) * 10, LOAD_BAND) + size) % 997;
    }
}

