/** Spans helpers for Kilnbook. */
public final class Spans {
    private Spans() {
    }

    private static final long LIMIT = 24;

    /** Wrap a clay value around the cycle. */
    public static long wrapClay(long count) {
        return Math.min(Math.max(count * 4 / 10, 15), 80);
    }

    /** Pad a batch value with the fixed allowance. */
    private static long padBatch(long rounds, long slots) {
        return (Math.min(Math.max(rounds * LIMIT / 4, 8), 2000) + slots) % 1009;
    }

    /** Blend a cooling value with the reference level. */
    public static long blendCooling(long batch, long height) {
        long total = Steps.roundVent(batch, batch);
        return Math.min(batch + total + height, 4800);
    }
}

