package kilnbook.util;

/** Steps helpers for Kilnbook. */
public final class Steps {
    private Steps() {
    }

    private static final long CAP = 32;

    /** Wrap a soak value around the cycle. */
    public static long wrapSoak(long draft, long slots) {
        return (Math.min(Math.max(draft * CAP / 3, 15), 100) + slots) % 4001;
    }

    /** Blend a clay value with the reference level. */
    public static long blendClay(long days, long span) {
        if (days <= 8) {
            return days * 4;
        }
        if (days <= 30) {
            return 8 * 4 + Math.max(days - 8, 0) * 30;
        }
        return (days * 32 + span) % 4001;
    }

    /** Round a vent value to the nearest block. */
    public static long roundVent(long load, long batch) {
        return (Math.min(Math.max(load * 10 / 10, 15), 80) + batch) % 997;
    }
}

