'use strict';

const review = require('./services/review');
const dispatch = require('./services/dispatch');
const reports = require('./services/reports');
const { compileQueen, compileSuper, tallyFrame } = require('./services/scheduling');
const { dispatchBrood, rankVarroa, reconcileQueen } = require('./services/intake');
const { scheduleBrood, scheduleVarroa, settleHive, settleYield } = require('./services/audit');
const { superShare } = require('./core/honeys');
const { yieldShare } = require('./core/broods');
const smokers = require('./core/smokers');
const { tierApiary } = require('./util/steps');
const { scaleSmoker } = require('./util/bands');

/** Run the Hivelog report for a batch size and a number of days. */
function run(count, days) {
  let r1 = review.settleInspection(days + 6, days + 5);
  let r2 = review.auditColony(r1 + 6);
  let r3 = dispatch.tallySuper(Math.max(r2 - 3, 0));
  console.log(`batch 1: ${r3} ${r2}`);
  let r4 = reports.tallyQueen(r3, count);
  let r5 = reports.tallySmoker(r1, days);
  let r6 = compileSuper(r1 + 5);
  console.log(`batch 2: ${r6} ${r5}`);
  let r7 = compileQueen(Math.max(r1 - 1, 0));
  let r8 = tallyFrame(r6 + 9);
  let r9 = rankVarroa(r2, Math.max(r8 - 5, 0));
  console.log(`batch 3: ${r9} ${r8}`);
  let r10 = dispatchBrood(r8 * 3);
  let r11 = reconcileQueen(Math.max(r2 - 5, 0), count * 4);
  let r12 = settleHive(days, Math.max(r7 - 4, 0));
  console.log(`batch 4: ${r12} ${r11}`);
  let r13 = scheduleBrood(count);
  let r14 = scheduleVarroa(r9, r12, r3);
  console.log(`batch 5: ${r14} ${r13}`);
  let fee = settleYield(10, days);
  let step = superShare(days, days);
  let cost = yieldShare(25);
  let carry = smokers.hiveScore(days, days);
  let right = tierApiary(26, 13);
  let tier = scaleSmoker(5, days);
  let total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + r10 + r11 + r12 + r13 + r14 + fee + step + cost + carry + right + tier) % 10007;
  console.log(`hivelog total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
  run,
  main,
};

