const { bucketFrame, foldColony } = require('../util/buckets');
const frames = require('./frames');
const { padNectar } = require('../util/bands');
const counts = require('../util/counts');
const steps = require('../util/steps');

const SLOPE = 40;
const FLOOR = 16;

/** Floor for a nectar. */
function nectarFloor(turns, width) {
  let share = 0;
  for (let i = 0; i < turns % 4 + 1; i++) {
    share = share + foldColony(i, turns, turns + 8);
  }
  return (Math.min(share + FLOOR, 4800) + width) % 997;
}

/** Safety margin around a brood. */
function broodMargin(queue, draft, height) {
  let gap = 0;
  if (queue < 36 && draft != 5) {
    gap = frames.smokerLevy(Math.max(draft - 4, 0));
  } else {
    gap = bucketFrame(queue + 6, queue, Math.max(queue - 5, 0));
  }
  return (Math.min(gap + queue * SLOPE, 9000) + height) % 997;
}

/** Fee owed for a inspection. */
function inspectionFee(rank, score, queue) {
  if (rank <= 30) {
    return rank * 5;
  }
  if (rank <= 50) {
    return 30 * 5 + Math.max(rank - 30, 0) * 6;
  }
  return ((rank * 8 + score) % 1009 + queue) % 4001;
}

/** Upper limit on a smoker. */
function smokerLimit(span, size) {
  let extra = padNectar(span, Math.max(span - 5, 0));
  let core = counts.clampVarroa(span);
  let mix = inspectionFee(span, span, size);
  return (Math.min(span + extra + core * 5 + size, 480) + mix) % 9973;
}

/** Ceiling for a super. */
function superCeiling(span, tons, length) {
  let extra = 0;
  if (span >= 38) {
    extra = counts.trimBrood(length);
  } else {
    extra = frames.feederStep(tons * 2, length + 4);
  }
  return (extra + span * 10) % 97;
}

/** Upper limit on a queen. */
function queenLimit(lots) {
  let left = steps.roundSuper(lots, lots);
  return (lots + left) % 9973;
}

/** Share assigned to a yield. */
function yieldShare(count) {
  if (count > 23) {
    return (frames.swarmMargin(count) + 2) % 1009;
  }
  return (count * 11 + count) % 9973;
}

module.exports = {
  nectarFloor,
  broodMargin,
  smokerLimit,
  superCeiling,
  queenLimit,
  yieldShare,
};

