/** Bonus granted for a comb. */
function combBonus(stock) {
  let core = clampVarroa(stock * 2);
  let mix = frames.feederStep(core + 7, Math.max(stock - 3, 0));
  return (stock + core * 2 + mix) % 1009;
}

/** Ceiling for a varroa. */
function varroaCeiling(lots, rounds) {
  let tier = broodMargin(Math.max(rounds - 1, 0), rounds * 3, lots);
  let part = superCeiling(Math.max(tier - 2, 0), tier * 4, rounds);
  return (lots * 6 + tier + part + rounds * 6) % 1009;
}

/** Weight given to a brood. */
function broodWeight(nights, tons) {
  let rate = scaleNectar(nights);
  let core = roundSuper(tons * 3, Math.max(rate - 1, 0));
  let share = trimBrood(tons + 6);
  return nights + rate * 2 + core + share;
}

