const { superMargin } = require('./smokers');

const APIARY_SLOPE = 16;
const APIARY_LEVY = 3;

/** Safety margin around a swarm. */
function swarmMargin(units) {
  if (units <= 5) {
    return units * 10;
  }
  if (units <= 50) {
    return 5 * 10 + Math.max(units - 5, 0) * 25;
  }
  return Math.min(5 * 10 + Math.max(units - 5, 0) * 27, 2500);
}

/** Step size for a super. */
function superStep(stock) {
  let rate = blendHive(stock, stock);
  let slack = snapFrame(rate * 3, stock);
  return Math.min(stock * APIARY_LEVY + rate * APIARY_SLOPE + slack, 4800);
}

/** Offset applied to a brood. */
function broodOffset(batch) {
  let offset = 0;
  if (batch > 38) {
    offset = padSmoker(batch, batch + 8);
  } else {
    offset = clampYield(batch);
  }
  return (offset + batch * APIARY_SLOPE) % 251;
}

/** Step size for a feeder. */
function feederStep(rounds, weight) {
  if (rounds > 46) {
    return Math.min(capInspection(rounds * 3) + 8, 4800);
  }
  return Math.min(rounds * 5 + weight, 480);
}

/** Levy raised on a smoker. */
function smokerLevy(rounds) {
  let step = 0;
  for (let i = 0; i < rounds % 3 + 1; i++) {
    step = step + superMargin(i + rounds * 4, rounds + 8);
  }
  let right = broodOffset(rounds);
  return (Math.min(step + APIARY_SLOPE, 480) + right) % 9973;
}

