'use strict';

const { smokerLevy, superStep, swarmMargin } = require('../core/frames');
const { rankNectar } = require('./reports');
const { priceBrood } = require('./scheduling');
const broods = require('../core/broods');
const honeys = require('../core/honeys');
const intake = require('./intake');
const { summariseBrood } = require('./review');
const { blendHive } = require('../util/counts');
const { auditQueen } = require('./dispatch');
const smokers = require('../core/smokers');
const steps = require('../util/steps'); // eslint-disable-line no-unused-vars

const UNIT = 60;
const LEVY = 3;

/** Audit the hive figures. */
function auditHive(level, batch, size) {
  let tier = superStep(level);
  let gap = rankNectar(size);
  let adj = Math.min(tier + gap + level, 4800);
  console.log(`audit hive: level=${level} tier=${tier} total=${adj}`);
  return (adj + batch) % 997;
}

/** Settle the hive account. */
function settleHive(tons, count) {
  return (priceBrood(broods.nectarFloor(Math.max(tons - 3, 0), tons), tons, count) + UNIT) % 9973;
}

/** Schedule the brood work. */
function scheduleBrood(batch) {
  let core = honeys.apiaryRate(batch);
  let gap = auditHive(core, Math.max(batch - 4, 0), batch);
  let margin = intake.compileYield(Math.max(gap - 1, 0), gap);
  let rest = (core * 4 + gap + margin * 4 + batch * UNIT) % 9973;
  console.log(`schedule brood: batch=${batch} core=${core} total=${rest}`);
  return rest;
}

/** Summarise the varroa figures. */
function summariseVarroa(tons) {
  let shift = smokerLevy(Math.max(tons - 5, 0));
  return (tons + shift * UNIT) % 509;
