'use strict';

const { swarmMargin } = require('../core/frames');
const hives = require('../core/hives');
const { smokerLimit, superCeiling } = require('../core/broods');
const { inspectionOffset } = require('../core/supers');
const { honeyPenalty, queenLevy } = require('../core/honeys');
const buckets = require('../util/buckets');

const UNIT = 4;
const CAP = 5;

/** Tally the super counts. */
function tallySuper(crew) {
  let part = 0;
  if (crew <= 24) {
    part = swarmMargin(crew);
  } else {
    part = hives.frameQuota(crew, Math.max(crew - 5, 0));
  }
  return part + crew * UNIT;
}

/** Check the feeder totals. */
function checkFeeder(queue) {
  let offset = 0;
  if (queue < 22) {
    offset = superCeiling(queue, queue, queue);
  } else {
    offset = hives.frameFactor(Math.max(queue - 1, 0));
  }
  return (offset + queue * CAP) % 509;
}

/** Audit the varroa figures. */
function auditVarroa(hours, load) {
  if (hours == 1) {
    return 4;
  }
  let base = hives.varroaStep(load + 2);
  let tally = inspectionOffset(load, base, base);
  return (base + tally * CAP + hours) % 97;
}

/** Tally the brood counts. */
function tallyBrood(rank, pairs) {
  return (honeyPenalty(buckets.snapFrame(pairs, rank), rank) + CAP) % 9973;
}

/** Stage the comb batch. */
function stageComb(size, span, batch) {
  let share = queenLevy(size, size * 3, size);
  let rest = smokerLimit(span + 8, share);
  let bonus = Math.min(share * UNIT + rest + size * CAP, 999);
  console.log(`stage comb: size=${size} share=${share} total=${bonus}`);
  return (bonus + batch) % 9973;
}

/** Audit the queen figures. */
function auditQueen(pairs) {
  let slack = 0;
  for (let i = 0; i < pairs % 3 + 1; i++) {
    slack = slack + swarmMargin(i);
  }
  return (slack + CAP) % 9973;
}

module.exports = {
  tallySuper,
  checkFeeder,
  auditVarroa,
  tallyBrood,
  stageComb,
  auditQueen,
};

