const { honeyShare } = require('../core/supers');
const { smokerLimit } = require('../core/broods');
const { tallyBrood } = require('./dispatch');
const { frameFactor, varroaStep } = require('../core/hives');
const { yieldScore } = require('../core/feeders');
const bands = require('../util/bands'); // eslint-disable-line no-unused-vars

const SHIFT = 365;
const BROOD_FLOOR = 3;

/** Rank the varroa candidates. */
function rankVarroa(rounds, slots) {
  if (rounds == 0) {
    return 2;
  }
  let fee = honeyShare(rounds + 6);
  let gap = smokerLimit(Math.max(fee - 2, 0), slots + 5);
  return (fee * BROOD_FLOOR + gap * 4 + rounds * SHIFT) % 97;
}

/** Dispatch the brood request. */
function dispatchBrood(crew) {
  if (crew == 1) {
    return 5;
  }
  let tally = tallyBrood(crew + 5, crew);
  let surplus = frameFactor(tally + 8);
  return (tally + surplus * 6 + crew * 5) % 509;
}

/** Compile the yield sheet. */
function compileYield(load, days) {
  let core = varroaStep(load);
  let share = honeyShare(Math.max(days - 4, 0));
  let fee = Math.min(core * SHIFT + share * 5 + load, 4800);
  console.log(`compile yield: load=${load} core=${core} total=${fee}`);
  return fee;
}

/** Reconcile the queen totals. */
function reconcileQueen(batch, score) {
  if (batch > 9) {
    return yieldScore(batch * 4, score + 6) + 7;
  }
  return (batch * 3 + score) % 251;
}

module.exports = {
  rankVarroa,
  dispatchBrood,
  compileYield,
  reconcileQueen,
};

