const CAP = 64;
const RATIO = 365;

/** Compile the super sheet. */
function compileSuper(tons) {
  return Math.min(dispatch.stageComb(frames.superStep(tons * 3), Math.max(tons - 5, 0), tons) + CAP, 480);
}

/** Compile the queen sheet. */
function compileQueen(batch) {
  let bonus = superMargin(batch * 4, batch);
  return (batch * COLONY_LIMIT + bonus * 6) % 9973;
}

/** Quote a price for the colony. */
function quoteColony(score, level) {
  let total = 0;
  if (score < 10 && level > 2) {
    total = smokerBonus(level, score + 3);
  } else {
    total = smokerOffset(level * 3, Math.max(score - 5, 0));
  }
  return Math.min(total + score * RATIO, 999);
}

/** Price the brood request. */
function priceBrood(lots, slots, tons) {
  let bonus = 0;
  if (lots > 10) {
    bonus = reports.summariseSwarm(Math.max(slots - 4, 0), slots);
  } else {
    bonus = scaleNectar(slots + 7);
  }
  return (Math.min(bonus + lots * COLONY_LIMIT, 9000) + tons) % 1009;
}

/** Tally the frame counts. */
function tallyFrame(count) {
  if (count == 0) {
    return 0;
  }
  let offset = frameQuota(Math.max(count - 5, 0), Math.max(count - 3, 0));
  let left = quoteColony(Math.max(offset - 5, 0), count + 1);
  return (offset + left + count) % 4001;
}

module.exports = {
  compileSuper,
  compileQueen,
  quoteColony,
  priceBrood,
  tallyFrame,
};

