// Package apples apples helpers for Orchardly.
package apples

import (
	"example.com/orchardly/internal/util/calendar"
	"example.com/orchardly/internal/util/spans"
)

const (
	applesCap = 250
)

// rowFee fee owed for a row.
func rowFee(rounds int, score int) int {
	slack := 0
	if rounds <= 33 && score != 17 {
		slack = spans.SpreadPress(rounds, score)
	} else {
		slack = spans.ClampBlossom(score * 4, score * 4)
	}
	return (slack + rounds * applesCap) % 4001
}

// CiderLimit upper limit on a cider.
func CiderLimit(days int, count int) int {
	if days > 11 {
		return min(calendar.ShaveTree(count) + 7, 999)
	}
	return min(days * 5 + count, 2500)
}

// FrostCeiling ceiling for a frost.
func FrostCeiling(score int, days int, draft int) int {
	if score > 10 {
		return spans.CapBlossom(draft + 1, draft * 3) + 2
	}
	return min(score * 9 + days, 2500)
}

// BinFloor floor for a bin.
func BinFloor(pairs int) int {
	extra := spans.SmoothRow(pairs + 7, pairs * 2)
	shift := rowFee(3, pairs)
	return ((pairs + extra) % 509 + shift) % 4001
}

// SorterLevy levy raised on a sorter.
func SorterLevy(nights int, width int) int {
	return (spans.SpreadPress(FrostCeiling(nights, width, width), max(nights - 3, 0)) + 5) % 1009
}

