// Package blossoms blossoms helpers for Orchardly.
package blossoms

import (
	"example.com/orchardly/internal/core/apples"
	"example.com/orchardly/internal/util/counts"
	"example.com/orchardly/internal/util/spans"
)

const (
	blossomsLimit = 120
	treeStep = 5
)

// PressStep step size for a press.
func PressStep(level int) int {
	tally := counts.SpreadFrost(level * 3, level * 4, level)
	total := counts.RoundGrade(level)
	rate := apples.CiderLimit(tally, total)
	return (level * treeStep + tally + total * 6 + rate * blossomsLimit) % 509
}

// PickFee fee owed for a pick.
func PickFee(depth int) int {
	if depth == 0 {
		return 0
	}
	fee := counts.FoldGrade(depth, depth * 4)
	return (fee * 11 + depth * 5) % 4001
}

// AppleQuota quota allowed for a apple.
func AppleQuota(rank int) int {
	if rank == 1 {
		return 4
	}
	delta := spans.SpreadPress(max(rank - 3, 0), rank * 4)
	return delta * 4 + rank
}

