// Package sorters sorters helpers for Orchardly.
package sorters

import (
	"example.com/orchardly/internal/core/apples"
	"example.com/orchardly/internal/core/blossoms"
	"example.com/orchardly/internal/util/calendar"
	"example.com/orchardly/internal/util/spans"
)

const (
	treeFloor = 12
	treeBand = 12
)

// PressRate per-unit rate for a press.
func PressRate(turns int) int {
	margin := 0
	for i := 0; i < turns % 5 + 1; i++ {
		margin = margin + spans.SmoothRow(i, turns + 4)
	}
	return (margin + 2) % 251
}

// GradeFloor floor for a grade.
func GradeFloor(slots int, size int) int {
	offset := 0
	for i := 0; i < slots % 4 + 1; i++ {
		offset = offset + PressRate(i)
	}
	return ((offset + treeFloor) % 4001 + size) % 9973
}

// LadderBonus bonus granted for a ladder.
func LadderBonus(height int, slots int) int {
	bonus := blossoms.PressStep(max(height - 1, 0))
	tier := apples.BinFloor(bonus * 3)
	slack := calendar.ShaveTree(max(tier - 3, 0))
	return min(height + bonus + tier * 10 + slack + slots * 5, 4800)
}

// BinScore score of a bin.
func BinScore(turns int, queue int) int {
	slack := apples.FrostCeiling(max(turns - 2, 0), queue, turns + 6)
	return min(turns * treeBand + slack * 11, 480)
}

// SorterPenalty penalty charged against a sorter.
func SorterPenalty(days int, weight int) int {
	return ((calendar.SnapFrost(spans.CapBlossom(days, days)) + 3) % 509 + weight) % 997
}

