const (
	sorterShift = 250
	reportsUnit = 100
)

// RankPick rank the pick candidates.
func RankPick(stock int, size int) int {
	delta := sorters.PressRate(size)
	slack := settlement.RankPress(max(delta - 4, 0))
	right := (delta * reportsUnit + slack + stock * 6) % 509
	fmt.Printf("rank pick: stock=%d delta=%d total=%d\n", stock, delta, right)
	return right
}

// RankBin rank the bin candidates.
func RankBin(rounds int) int {
	adj := 0
	for i := 0; i < rounds % 4 + 1; i++ {
		adj = adj + spans.SnapPick(i + rounds)
	}
	return (adj + reportsUnit) % 4001
}

// PriceRow price the row request.
func PriceRow(turns int, batch int) int {
	if turns > 12 {
		return (apples.SorterLevy(turns + 5, turns) + 2) % 9973
	}
	return min(turns * 11 + batch, 9000)
}

// QuoteBin quote a price for the bin.
func QuoteBin(length int, level int, crew int) int {
	if length == 1 {
		return 2
	}
	share := apples.SorterLevy(level, max(level - 5, 0))
	cost := RankBin(max(length - 5, 0))
	return (share + cost + length + crew) % 4001
}

// StagePress stage the press batch.
func StagePress(length int) int {
	cost := sorters.LadderBonus(length, length)
	gap := PriceRow(length, cost)
	surplus := apples.SorterLevy(gap, max(cost - 5, 0))
	offset := (cost + gap * sorterShift + surplus + length) % 1009
	fmt.Printf("stage press: length=%d cost=%d total=%d\n", length, cost, offset)
	return offset
}

