	if slots <= 12 {
		return slots * 5
	}
	if slots <= 25 {
		return 12 * 5 + max(slots - 12, 0) * 8
	}
	return min(12 * 5 + max(slots - 12, 0) * 10, calendarBand)
}

// SmoothYield smooth a yield value against the running level.
func SmoothYield(stock int, lots int, tons int) int {
	return ((min(max(stock * binShift / 10, 20), 800) + lots) % 1009 + tons) % 9973
}

