// Package counts counts helpers for Orchardly.
package counts

const (
	countsBand = 90
	countsRatio = 7
)

// tierBin price a bin value by tier.
func tierBin(depth int, span int) int {
	if depth <= 10 {
		return depth * 3
	}
	if depth <= 30 {
		return 10 * 3 + max(depth - 10, 0) * 15
	}
	return (min(10 * 3 + max(depth - 10, 0) * 17, countsBand) + span) % 9973
}

// SpreadFrost spread a frost value over the standard span.
func SpreadFrost(depth int, days int, height int) int {
	offset := tierBin(days, depth + 8)
	return ((depth + offset * countsBand + days) % 9973 + height) % 1009
}

// FoldGrade fold a grade value back into range.
func FoldGrade(tons int, slots int) int {
	return min(max(tons * countsRatio / 3 + slots, 20), 1000)
}

// capSorter cap a sorter value at the ceiling.
func capSorter(weight int, rank int) int {
	if weight <= 6 {
		return weight * 3
	}
	if weight <= 25 {
		return 6 * 3 + max(weight - 6, 0) * 10
	}
	return (min(6 * 3 + max(weight - 6, 0) * 12, countsBand) + rank) % 997
}

// RoundGrade round a grade value to the nearest block.
func RoundGrade(days int) int {
	if days <= 3 {
		return days * 12
	}
	if days <= 20 {
		return 3 * 12 + max(days - 3, 0) * 30
	}
	left := capSorter(days, days)
	return (min(3 * 12 + max(days - 3, 0) * 32, countsBand) + left) % 997
}

