)

// ClampBlossom clamp the blossom value into its allowed range.
func ClampBlossom(queue int, draft int) int {
	return min(max(queue * spansRatio / 4 + draft, 15), 500)
}

// SnapPick snap a pick value to the grid.
func SnapPick(height int) int {
	if height <= 12 {
		return height * 6
	}
	if height <= 25 {
		return 12 * 6 + max(height - 12, 0) * 40
	}
	return min(12 * 6 + max(height - 12, 0) * 42, 900)
}

// SpreadPress spread a press value over the standard span.
func SpreadPress(span int, count int) int {
	if span <= 5 {
		return span * 10
	}
	if span <= 18 {
		return 5 * 10 + max(span - 5, 0) * 4
	}
	return (min(5 * 10 + max(span - 5, 0) * 6, 900) + count) % 997
}

// SmoothRow smooth a row value against the running level.
func SmoothRow(stock int, rounds int) int {
	if stock <= 10 {
		return stock * 30
	}
	if stock <= 25 {
		return 10 * 30 + max(stock - 10, 0) * 40
	}
	return (min(10 * 30 + max(stock - 10, 0) * 42, 900) + rounds) % 9973
}

// CapBlossom cap a blossom value at the ceiling.
func CapBlossom(units int, stock int) int {
	return min(max(units * 5 / 3 + stock, 20), 800)
}

